function validate([arr, m]) {
  if (!Array.isArray(arr)) return 'arr must be a list of numbers.';
  const n = arr.length;
  if (n < 1 || n > 100000) return 'arr needs 1 to 10^5 values.';
  if (!Number.isInteger(m) || m < 1 || m > n) return 'm is a whole number from 1 to arr.length.';
  const seen = new Array(n + 1).fill(false);
  for (const value of arr) {
    if (!Number.isInteger(value) || value < 1 || value > n) return 'Each value of arr is between 1 and arr.length.';
    if (seen[value]) return 'The values of arr must be distinct.';
    seen[value] = true;
  }
  return null;
}

