function findLatestStep(arr, m) {
  const n = arr.length;
  const length = new Array(n + 2).fill(0);
  const count = new Array(n + 1).fill(0);
  let latest = -1;

  for (let step = 0; step < n; step++) {
    const position = arr[step];
    const leftLength = length[position - 1];
    const rightLength = length[position + 1];
    const merged = leftLength + rightLength + 1;
    length[position - leftLength] = merged;
    length[position + rightLength] = merged;
    count[leftLength]--;
    count[rightLength]--;
    count[merged]++;
    if (count[m] > 0) {
      latest = step + 1;
    }
  }
  return latest;
}

