function findLatestStep(arr, m) {
  // Rebuild the bit row after every step and measure all of its runs from scratch.
  const n = arr.length;
  const bits = new Array(n).fill(0);
  let answer = -1;
  arr.forEach((p, i) => {
    bits[p - 1] = 1;
    let run = 0;
    let found = false;
    for (let k = 0; k <= n; k++) {
      if (k < n && bits[k] === 1) run++;
      else {
        if (run === m) found = true;
        run = 0;
      }
    }
    if (found) answer = i + 1;
  });
  return answer;
}

