function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const arr = Array.from({ length: n }, (_, i) => i + 1);
  const style = rand();
  if (style < 0.15) {
    // Fill from left to right, which builds one growing group.
  } else if (style < 0.25) {
    arr.reverse();
  } else {
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  const roll = rand();
  let m;
  if (roll < 0.1) m = n;
  else if (roll < 0.3) m = 1;
  else if (size === 'large' && roll < 0.8) m = 1 + Math.floor(rand() * 40);
  else m = 1 + Math.floor(rand() * n);
  return [arr, m];
}
